package ru.meguboom.mobile;
import org.json.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Shared v1 wire contract; timestamps win even for rewinds and completion removal. */
final class ProgressRecords {
 static final int MAX_BYTES=2*1024*1024,MAX_ENTRIES=20000;
 static boolean validId(String id){return id!=null&&!Arrays.asList("__proto__","constructor","prototype").contains(id)&&id.matches("[A-Za-z0-9_-]{1,200}");}
 static boolean uuid(String id){return id!=null&&id.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");}
 static long integer(JSONObject o,String key,boolean positive)throws Exception{Object v=o.get(key);if(!(v instanceof Number))throw new IOException("Некорректное число");double numeric=((Number)v).doubleValue();if(!Double.isFinite(numeric)||Math.rint(numeric)!=numeric||numeric>9007199254740991d)throw new IOException("Некорректное целое число");long n=((Number)v).longValue();if(n<(positive?1:0)||n>9007199254740991L)throw new IOException("Число вне диапазона");return n;}
 static JSONObject parse(String text)throws Exception{if(text.getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)throw new IOException("Слишком большой файл прогресса");JSONObject body=new JSONObject(text);if(integer(body,"version",true)!=1||!uuid(body.optString("deviceId")))throw new IOException("Неизвестный формат прогресса");JSONObject entries=body.getJSONObject("entries");if(entries.length()>MAX_ENTRIES)throw new IOException("Слишком много записей");for(Iterator<String> it=entries.keys();it.hasNext();){String id=it.next();if(!validId(id))throw new IOException("Некорректный идентификатор");JSONObject r=entries.getJSONObject(id);integer(r,"positionMs",false);integer(r,"durationMs",false);integer(r,"updatedAt",true);if(!(r.get("completed") instanceof Boolean)||!uuid(r.optString("deviceId")))throw new IOException("Некорректная запись прогресса");}return entries;}
 static JSONObject document(String device,JSONObject entries)throws JSONException{return new JSONObject().put("version",1).put("deviceId",device).put("entries",entries);}
 static boolean newer(JSONObject a,JSONObject b){return b==null||a.optLong("updatedAt")>b.optLong("updatedAt")||a.optLong("updatedAt")==b.optLong("updatedAt")&&a.optString("deviceId").compareTo(b.optString("deviceId"))>0;}
 static boolean merge(JSONObject target,JSONObject incoming)throws JSONException{boolean changed=false;for(Iterator<String> it=incoming.keys();it.hasNext();){String id=it.next();JSONObject r=incoming.getJSONObject(id);if(newer(r,target.optJSONObject(id))&&(target.has(id)||target.length()<MAX_ENTRIES)){target.put(id,new JSONObject(r.toString()));changed=true;}}return changed;}
 static String fileId(JSONObject record){if(record==null)return "";String id=record.optString("fileId");if(validId(id))return id;id=record.optString("downloadOf",record.optString("id"));if(id.startsWith("drive-"))id=id.substring(6);else return "";return validId(id)?id:"";}
}
